parameters.start:
={{ (function(){
  const raw = String($fromAI('Start', `For a normal timed booking, an ISO 8601 start datetime with timezone, e.g. 2026-01-06T09:00:00+08:00. For an M Booth all-day booking (All Day set to true), pass just the date instead, with no time or timezone, e.g. 2026-01-06.`, 'string') || '').trim();
  if (!raw) { throw new Error('No start was supplied. Nothing was created.'); }
  const d = raw.length <= 10 ? DateTime.fromISO(raw, { zone: 'Asia/Manila' }) : DateTime.fromISO(raw);
  if (!d.isValid) { throw new Error('The start could not be read as a date: "' + raw + '". Ask the requester to restate the date and time. Nothing was created.'); }
  if (d < DateTime.now().setZone('Asia/Manila').startOf('day')) {
    throw new Error('BLOCKED - that date has already passed. Tell the requester the date is in the past and ask them to confirm the correct one. Do not call this tool again until they give you a new date. Nothing was created.');
  }
  return raw;
})() }}

